import boto3

def check_unsafe_text(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_sentiment(
        Text=text,
        LanguageCode='en'
    )
    sentiment = response['Sentiment']
    if sentiment == 'NEGATIVE':
        return True
    return False

def check_secret_labels_and_notes(labels, notes):
    for label in labels:
        if check_unsafe_text(label):
            return True
    for note in notes:
        if check_unsafe_text(note):
            return True
    return False

from typing import Any, Dict, List

class SecretRequest:
    def __init__(self, secret_id: str, version_id: str = None):
        self.secret_id = secret_id
        self.version_id = version_id

    def to_dict(self) -> Dict[str, Any]:
        return {
            'secret_id': self.secret_id,
            'version_id': self.version_id
        }


class SecretResponse:
    def __init__(self, secret_id: str, version_id: str, secret_value: str):
        self.secret_id = secret_id
        self.version_id = version_id
        self.secret_value = secret_value

    @classmethod
    def from_dict(cls, data: Dict[str, Any]):
        return cls(
            secret_id=data['secret_id'],
            version_id=data['version_id'],
            secret_value=data['secret_value']
        )


def normalize_secret_response(response: Dict[str, Any]) -> SecretResponse:
    return SecretResponse.from_dict(response)

import boto3

class SecretManagementClient:
    def __init__(self, region_name='us-west-2'):
        self.client = boto3.client('secretsmanager', region_name=region_name)

    def get_secret_value(self, secret_name):
        response = self.client.get_secret_value(SecretId=secret_name)
        return response['SecretString']

    def list_secrets(self):
        response = self.client.list_secrets()
        return response['SecretList']

import boto3
import json

def parse_json_secret(secret_name):
    client = boto3.client('secretsmanager')
    get_secret_value_response = client.get_secret_value(
        SecretId=secret_name
    )
    secret = get_secret_value_response['SecretString']
    return json.loads(secret)

import boto3

def fetch_api_key(secret_name):
    client = boto3.client('secretsmanager')
    get_secret_value_response = client.get_secret_value(
        SecretId=secret_name
    )
    if 'SecretString' in get_secret_value_response:
        secret = get_secret_value_response['SecretString']
        return secret
    else:
        raise ValueError('Secret not found')
